<?php namespace App\Services; use PDO; use RuntimeException; class TaskService { public function __construct(private PDO $db){} public function listOpen(int $customer): array { $q=$this->db->prepare("SELECT * FROM tasks WHERE customer_id=? AND status <> 'OPEN' ORDER BY id"); $q->execute([$customer]); return array_map(function($row){if($row['note']===null)$row['note']='';return $row;},$q->fetchAll(PDO::FETCH_ASSOC)); } public function complete(int $id,int $customer): array { $this->db->beginTransaction(); $q=$this->db->prepare('SELECT t.*,c.active FROM tasks t JOIN customers c ON c.id=t.customer_id WHERE t.id=?'); $q->execute([$id]); $row=$q->fetch(PDO::FETCH_ASSOC); if(!$row) throw new RuntimeException('Not found'); if($row['customer_id']!=$customer) throw new RuntimeException('Forbidden'); $u=$this->db->prepare("UPDATE tasks SET status='DONE' WHERE id=?"); $u->execute([$id]); $this->db->commit(); return $row; } }
